#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int stoneGameVII(vector<int>& stones) {
        int n = stones.size();
        vector<int> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + stones[i];
        vector<int> dp(n, 0);
        for (int len = 2; len <= n; ++len) {
            for (int i = 0; i <= n - len; ++i) {
                int j = i + len - 1;
                int pick_left = (pref[j + 1] - pref[i + 1]) - dp[i + 1];
                int pick_right = (pref[j] - pref[i]) - dp[i];
                dp[i] = max(pick_left, pick_right);
            }
        }
        return dp[0];
    }
};

class Solution {
    public int stoneGameVII(int[] stones) {
        int n = stones.length;
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + stones[i];
        int[] dp = new int[n];
        for (int len = 2; len <= n; ++len) {
            for (int i = 0; i <= n - len; ++i) {
                int j = i + len - 1;
                int pickLeft = (pref[j + 1] - pref[i + 1]) - dp[i + 1];
                int pickRight = (pref[j] - pref[i]) - dp[i];
                dp[i] = Math.max(pickLeft, pickRight);
            }
        }
        return dp[0];
    }
}

